 private static double wavPeak(byte[] b){require(b.length>44&&b[0]=='R'&&b[8]=='W',"invalid WAV");double peak=0;for(int i=44;i+1<b.length;i+=2)peak=Math.max(peak,Math.abs((short)((b[i]&255)|(b[i+1]<<8)))/32768.0);return peak;}

