 private static Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 private void barrier(EngineController controller)throws Exception{CountDownLatch done=new CountDownLatch(1);((Handler)field(controller,"worker")).post(done::countDown);require(done.await(10,TimeUnit.SECONDS),"engine worker did not settle");}
 private static void delay(long ms){SystemClock.sleep(ms);}
